      { V := V_1, addCommGroup := addCommGroup_1, module := module_1, ρ := ρ_1, smooth := smooth_1 } →
    V = V_1 ∧ addCommGroup ≍ addCommGroup_1 ∧ module ≍ module_1 ∧ ρ ≍ ρ_1

